   292  static bool IsAlpha(char c) {
   293    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
   294  }
   295
   296  static bool IsDigit(char c) {
   297    return c >= '0' && c <= '9';
   298  }
